import{_ as t,o as a,c as r,a9 as o}from"./chunks/framework.asyjyako.js";const g=JSON.parse('{"title":"VS Code video walkthroughs","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode-videos.md","filePath":"interfaces/vscode-videos.md","lastUpdated":null}'),i={name:"interfaces/vscode-videos.md"};function s(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="VS-Code-video-walkthroughs" tabindex="-1">VS Code video walkthroughs <a class="header-anchor" href="#VS-Code-video-walkthroughs" aria-label="Permalink to &quot;VS Code video walkthroughs {#VS-Code-video-walkthroughs}&quot;">​</a></h1><p>Start with a performance question, run the relevant check, then inspect the saved evidence. The walkthrough series follows that path in short chapters. Each chapter has a written guide that you can follow independently of a video.</p><h2 id="Choose-a-chapter" tabindex="-1">Choose a chapter <a class="header-anchor" href="#Choose-a-chapter" aria-label="Permalink to &quot;Choose a chapter {#Choose-a-chapter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Chapter</th><th style="text-align:right;">What you will do</th><th style="text-align:right;">Written guide</th></tr></thead><tbody><tr><td style="text-align:right;">Introduction</td><td style="text-align:right;">Read a measured comparison and decide what to investigate next</td><td style="text-align:right;"><a href="./../guide/investigate">Investigate a workload</a></td></tr><tr><td style="text-align:right;">1 — Installation and a first result</td><td style="text-align:right;">Choose the Julia runtime and controller, run a TestItem, then open its result</td><td style="text-align:right;"><a href="./vscode-configuration">Configure VS Code</a> and <a href="/PerfChecker/dev/interfaces/vscode#Get-a-first-result">get a first result</a></td></tr><tr><td style="text-align:right;">2 — Configure a comparison</td><td style="text-align:right;">Select checks, workloads and versions or commits before running a suite</td><td style="text-align:right;"><a href="/PerfChecker/dev/interfaces/vscode#Design-a-suite-and-compare-targets">Design a suite</a> and <a href="./../tutorials/comparisons">compare targets</a></td></tr><tr><td style="text-align:right;">3 — Read measurements</td><td style="text-align:right;">Inspect distributions, allocations and profiles; check units and comparison limits</td><td style="text-align:right;"><a href="/PerfChecker/dev/interfaces/vscode-workflows#Plot-saved-results">Read saved plots</a> and <a href="./../guide/understanding-measurements">understand measurements</a></td></tr><tr><td style="text-align:right;">4 — Choose an interface</td><td style="text-align:right;">Use the editor, a Julia REPL, Pluto or the Web interface for the same investigation</td><td style="text-align:right;"><a href="./vscode-workflows">VS Code workflows</a>, <a href="./repl-pluto">REPL and Pluto</a> and <a href="./web-studio">Web interface</a></td></tr><tr><td style="text-align:right;">5 — Discuss and review a change</td><td style="text-align:right;">Select saved evidence, ask follow-up questions, review a proposal, verify it and restore when needed</td><td style="text-align:right;"><a href="./../mcp-advisor">MCP advice and implementation</a></td></tr></tbody></table><p>Shorts focus on one action or result. They supplement these chapters; the written guides contain the prerequisites, complete steps and recovery actions.</p><h2 id="Full-tutorial" tabindex="-1">Full tutorial <a class="header-anchor" href="#Full-tutorial" aria-label="Permalink to &quot;Full tutorial {#Full-tutorial}&quot;">​</a></h2><p>For the complete workflow, follow the chapters above in order. After your first result, check the saved measurements before choosing another collector or asking the advisor for an explanation. Preparing or applying an implementation is an explicit action, separate from advice.</p><p>Before following a chapter, check the release requirements and platform scope in <a href="./vscode-configuration">VS Code configuration</a> and <a href="/PerfChecker/dev/interfaces/vscode#Qualification-and-reporting-a-problem">qualification and reporting a problem</a>.</p><h2 id="Watch-on-YouTube" tabindex="-1">Watch on YouTube <a class="header-anchor" href="#Watch-on-YouTube" aria-label="Permalink to &quot;Watch on YouTube {#Watch-on-YouTube}&quot;">​</a></h2><p>The new series is not yet published on YouTube. Published episodes will be linked here when available. Until then, use the written guides above; local review recordings are not public episodes.</p>',10)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
